"""Write docs/REPORT_ee_nodes.md from validate_out.json (run after validate.py)."""
import json, glob
from lib import ROOT, AREAS
from presets import SPEC
v = json.load(open(ROOT + '/tools/ee_nodes/validate_out.json'))
st = v['stats']
nodes = []
for f in sorted(glob.glob(ROOT + '/data/nodes/ee_*.json')): nodes += json.load(open(f))
tr = json.load(open(ROOT + '/data/tracks/ee.json'))
L = []
A = L.append
A('# EE content graph: report\n')
A('Generated by `tools/ee_nodes/run_all.sh` (generators `g_*.py` -> `finalize.py` -> `track.py` -> `validate.py` -> `report.py`). Validation passes with 0 errors.\n')
A('## Files written\n')
A('- `data/nodes/ee_*.json` (18 files: `ee_hubs`, `ee_math`, `ee_physics`, `ee_programming`, `ee_circuits`, `ee_electronics`, `ee_digital`, `ee_architecture`, `ee_signals`, `ee_dsp`, `ee_em`, `ee_devices`, `ee_control`, `ee_comm`, `ee_power`, `ee_labs`, `ee_electives`, `ee_teardown`)')
A('- `data/tracks/ee.json` (19 sections: Overview, the 16 syllabus areas, teardowns, processes)')
A('- `tools/ee_nodes/` (`lib.py`, `g_*.py`, `finalize.py`, `track.py`, `validate.py`, `syllabus_map.py`, `presets.py`, `wiki_links.py`, `check_urls.py`, `report.py`, `run_all.sh`)')
A('- Nothing existing was edited. **To wire in:** add the 18 `ee_*.json` names to `data/nodes/manifest.json` and register the track in whatever lists `data/tracks/`.\n')
A('## Counts\n')
A(f'- **{st["total"]} nodes**, {st["edges_needs"]} prerequisite (`needs`) edges, acyclic (topological sort checked), track order respects needs.')
A(f'- Templates: {st["templates"]}; kinds: {st["kinds"]}')
A(f'- Certainty: {st["certainty"]} (C2/C3 nodes carry `open_questions`: grid_renewables_smart, photonic_integrated_circuits, wireless_5g6g, hardware_security as C2; quantum_computing_hardware as C3)')
A(f'- With OpenStax `refs`: {st["with_refs"]}; with `ext` links: {st["with_ext"]}; with neither: {st["no_refs_no_ext"]} (see Gaps)')
A(f'- With `lab`: {st["with_lab"]}; with `formula`: {st["with_formula"]}; with `where`: {st["with_where"]}; syllabus lines mapped: {st["syllabus_lines"]}')
A('\nNodes per area:\n')
A('| Area | Nodes |\n|---|---|')
for aid, t in AREAS: A(f'| {t} (`{aid}`) | {st["area"].get(aid,0)} |')
A(f'| Smartphone/charger teardown (`ee_teardown`) | {st["area"].get("ee_teardown",0)} |')
A(f'| Processes (`ee_processes`) | {st["area"].get("ee_processes",0)} |')
A(f'| Root | {st["area"].get("electrical_engineering",0)} |')
A('\nNote: the grid chain (7 nodes + `electric_power_grid`) and the end of the logic chain (`logic_adder`, `logic_gate_nand` in digital; `cmos_inverter` in electronics; `finfet_transistor`, `silicon_channel` in devices) are counted under their syllabus area so they appear in that track section; their teardown parent links are in `parents`/`parts`/`hotspot`.\n')
A('## Schema notes (additions and conventions)\n')
A('Same fields as `body_*.json`, plus: `needs`, `lab {id,preset}`, `where`, `formula`, `ext [{title,url}]`, `area` (hub id the node belongs to), `hotspot {of,at,label}`, `open_questions` (C2/C3), `steps` (process template, `focus` ids all validated).')
A('- `parents` = hierarchy (hub or physical parent), `parts` = auto-filled inverse of `parents` (hubs list their concept children), `needs` = prerequisite concept graph.')
A('- `where` is the **id of the deepest teardown node** where the concept lives (e.g. `alu_design -> core_alu`, `rectifiers -> rectifier_bridge`). The full path is obtained by walking `hotspot.of` upwards; no concatenated path ids are stored.')
A('- Hotspot coordinates are in the parent frame (metres). Phone frame per the brief (origin centre, +Y up the long edge, +Z out of the screen); PCB/SoC/cluster/core/ALU/adder/NAND/inverter/FinFET frames are local boxes sized to each node `scale_m`; the grid frame is ~100 km wide with +X from plant to outlet. Positions are plausible, not measured.')
A('- Root `electrical_engineering` and 16 hubs (`ee_*`) have `kind: field`. `made_of` of `silicon_channel` = `silicon` (crystal id in crystals.json).')
A('- `kn` links only point to ids in `data/knowledge/nodes.json` (validated).\n')
A('## Process nodes\n')
for n in nodes:
    if n['template'] == 'process': A(f'- `{n["id"]}` ({len(n["steps"])} steps): {n["title"]}')
A('\n## Planned lab presets (to build)\n')
A(f'{len(v["planned"])} presets are referenced that are not in the existing circuit/device lists. All other `circuit`/`device` presets used are from the brief list.\n')
A('| Lab:preset | Used by | Spec |\n|---|---|---|')
for k in sorted(v['planned']):
    l, p = k.split(':')
    A(f'| `{k}` | {", ".join(v["planned"][k][:4])}{" ..." if len(v["planned"][k])>4 else ""} | {SPEC[(l,p)]} |')
A('\n## Syllabus coverage (every bullet of lines 64-335)\n')
A('| Syllabus line | Nodes |\n|---|---|')
for line, ids in v['coverage']:
    A(f'| {line.replace("|","/")} | {" ".join("`"+i+"`" for i in ids)} |')
A('\n## Gaps and caveats\n')
A('- **Textbook refs are sparse by design.** OpenStax has no circuits, electronics, DSP, controls, comms or computer-architecture book, so only math/physics/chemistry/statistics/data-science nodes carry `refs` (all validated against `books.json`). Other nodes carry `ext` links.')
A('- **`ext` URLs were not network-verified**: the sandbox proxy returns 403 for wikipedia.org and ocw.mit.edu. Links are to long-standing Wikipedia article titles and a handful of course/textbook roots (MIT OCW 18.06 and RES.6-007, All About Circuits, Control Tutorials for MATLAB, DSP Guide, Python docs, NumPy docs, KiCad docs). Run `python3 tools/ee_nodes/check_urls.py` from a networked machine and drop any non-200 (candidates for typos: `Hardware_security`, `Hybrid-pi_model`, `Root_locus_analysis`).')
A(f'- {st["no_refs_no_ext"]} nodes have neither refs nor ext (hubs, a few ICs/analog topics): ' + ', '.join(n['id'] for n in nodes if not n['refs'] and not n.get('ext')))
A('- No OpenStax *Introduction to Python Programming*, *Introduction to Computer Science* or *Principles of Data Science* sections apply to C/embedded/HDL; only `DSC` (ML, time series) is used.')
A('- Prose is original and compact (3 layers per node, 1-3 sentences each); depth varies: circuits/electronics/digital are the most detailed, electives are survey-level. Numeric facts in expert layers are typical values from memory and should get a domain-expert review before publication (especially phone/charger/grid figures).')
A('- Teardown figures describe a generic 2024-class flagship, not a specific model. Hotspot positions are illustrative.')
A('- Syllabus subheadings (e.g. "Fundamentals") are not individually mapped; all bullets under them are.')
A('- The `lab` presets for `signal/logic/control/field/math/network/code` do not exist yet; node data is ready for them. `circuit:three_phase`, `inverter_bridge`, `buck_converter`, `boost_converter`, `flyback_converter` and `device:flash_cell` also need building (listed above).')
A('- Cross-area `needs` only point backwards in track order (checked). Where a natural prerequisite lived in a later area (e.g. sampling theorem for ADCs) a `related` link is used instead.\n')
open(ROOT + '/docs/REPORT_ee_nodes.md', 'w').write('\n'.join(L) + '\n')
print('report written', len(L), 'lines')
